import React, {useState, useRef} from 'react';
import './loginRegisterStyle.scss';
import ImageImport from '../img/ImageImport.png';
import {Link} from 'react-router-dom';
import {sha256} from 'crypto-hash';

const Register = () => {
    /*
    const [getUser, setUser] = useState();
    const [getPassword1, setPassword1] = useState();
    const [getPassword2, setPassword2] = useState();
    */
   // document.getElementById("submitButton").disabled = (pasword1Ref === pasword2Ref? false : true);
   
   const userRef = useRef( );
   const pasword1Ref = useRef( );
   const pasword2Ref = useRef( );
   
   /*
   const handleSubmit = (event) =>{
        //console.log(sha256(getUser));
        //console.log(sha256(getPassword1));
        //console.log(sha256(getPassword2));
        event.preventDefault();
        const user = userRef.current.value;
        const pw1 = pasword1Ref.current.value;
        const pw2 = pasword2Ref.current.value;
        //console.log(sha256(user));
        //console.log(sha256(pw1));
        //console.log(sha256(pw2));

        var jsonData = {
            "users": [
                {
                    "name": "alan", 
                    "age": 23,
                    "username": "aturing"
                },
                {
                    "name": "john", 
                    "age": 29,
                    "username": "__john__"
                }
            ]
          }
        fetch('/register')
          .then(res => res.json())
          .then(data => console.log({ data }));
    }*/

    const handleSubmit = async (e) => {
        e.preventDefault();
        alert("User Added")
        const userData = {
          user: userRef.current.value,
          password: pasword1Ref.current.value,
        };
    
       try{
        const add = await fetch("http://localhost:8080/", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify(userData),
        });
      console.log(add)
       }catch(err){
         console.error()
         console.log("error")
       }
      };

      async function onSubmit(e) {
        e.preventDefault()
        const form = e.target
        const rawdata = new FormData(form)
        const postData = {
          vname: rawdata.get('vname'),
          nname: rawdata.get('nname'),
          email: rawdata.get('email'),
          praktikum: rawdata.get('praktikum'),
          ausbildung: rawdata.get('ausbildung'),
          studium: rawdata.get('studium')
        }
        try {
          const res = await fetch('http://localhost:8080/', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json'
            },
            body: JSON.stringify(postData)
          })
          const result = await res.json()
          console.log('Success:', result)
          setSend(true)
        } catch (error) {
          console.error('Error:', error)
        }
      }
    

    const validate = () => {
        let abc = pasword1Ref.current.value === pasword2Ref.current.value ? true : false;
        console.log(pasword1Ref.current.value);
        console.log(pasword2Ref.current.value);
        console.log(abc);
        return abc
    };

    return (
    <div className='container'>
        <div className='wrapper'>
            <span className='logo'>Chatapp</span>
            <span className='title'>Registrierung</span>
            <form onSubmit={handleSubmit}>
            {/*<form>*/}
                <input type="text" name='user' placeholder="Benutzername" ref={userRef}/>
                <input type="password" name='password' placeholder="Passwort" ref={pasword1Ref}/>
                <input type="password" name='password' placeholder="Passwort erneut" ref={pasword2Ref}/>
                <input style={{display:"none"}} type="file" id="file"/>
                <label htmlFor='file'>
                    <img src={ImageImport} alt=''/>
                    <span>gibt ein Profilfoto an</span>
                </label>
                <button type='submit' disabled={!validate}>Registrieren</button>
            </form>
            <p>Du hast schon einen Account? <Link to="/login">Login</Link></p>
        </div>
    </div>
  )
}

export default Register
